export const getGetStatsUrl = (params: GetStatsParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/stats/?${stringifiedParams}` : `/stats/`
}

/**
 * @summary Get workout stats for a period
 */
export const getStats = async (params: GetStatsParams, options?: Parameters<typeof customFetch>[1]): Promise<getStatsResponse> => {

  return customFetch<getStatsResponse>(getGetStatsUrl(params),
  {
    ...options,
    method: 'GET'


  }
);}



